-- The sheet's alert threshold: a person whose due-total crosses above it is alerted in the audit; null: off. Not dated.
ALTER TABLE sheet ADD COLUMN alert_threshold DECIMAL(15, 2);
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.util.Map;

/**
 * A sheet's figures at one moment: each person's claimed, due-total and overdue-total (by person id, in the
 * order of the list) and the sheet's claimed-total, due-total and overdue-total, each as shown (two decimals; a due-total may be n/a),
 * and the sheet's alert threshold (null: off).
 */
public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal,
        BigDecimal alertThreshold) {

    /** Whether the due-total as shown (n/a or null: none) is above the threshold (null: off). */
    public static boolean above(String dueTotal, BigDecimal threshold) {
        return threshold != null && dueTotal != null && !dueTotal.equals("n/a")
                && new BigDecimal(dueTotal).compareTo(threshold) > 0;
    }

    /** A person's name and figures. */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {

        /** Whether the figures are the same as the other's, whatever the name. */
        public boolean sameAs(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
                    && overdueTotal.equals(other.overdueTotal);
        }
    }
}
import { ClaimRowValues } from '../../slots/defs/claimRow';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { ClaimDue } from './ClaimDue';
import { PersonDueTotal } from './PersonDueTotal';
import { PersonExcess } from './PersonExcess';

export const contributions = [
  PersonColumnHeads.fill({ order: 15, Component: () => <th>Due</th> }),
  PersonColumns.fill({ order: 15, Component: PersonDueTotal }),
  PersonColumnHeads.fill({ order: 15.5, Component: () => <th>Excess</th> }),
  PersonColumns.fill({ order: 15.5, Component: PersonExcess }),
  ClaimRowValues.fill({ order: 10, Component: ClaimDue }),
];
import { useClaims } from '../claims/claims';
import { liveHolds } from '../people/people';
import type { Person } from '../people/people';
import { useDueRules } from '../settings/settings';
import { personDue, useRates } from './rates';

// A person's due-total: the figures of their claims that count, added up; n/a when their grade has no
// rate on the sheet's today, unless a settled or stated claim keeps a figure.
export function PersonDueTotal({ person }: { person: Person }) {
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  return <td data-testid="person-due-total">{personDue(claims, rates, person.grades, liveHolds(person, rules.today), rules)}</td>;
}
