cd /home/daniel/ui-work/runs/202610271-to/sandbox/officehq-tanstack-officefloor/src/main/frontend; mkdir -p features/snapshots
cat > features/snapshots/snapshots.ts <<'EOF'
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';

/** That the person `personId`'s due-total stood at `dueTotal` (as shown) as the sheet left `day`. */
export type Snapshot = { personId: number; day: string; dueTotal: string };

/** The query key for the sheet's snapshots; under sheetKey, so re-loading the sheet or moving its today re-reads them. */
export const snapshotsKey = (sheet: string) => [...sheetKey(sheet), 'snapshots'] as const;

/** Every person's snapshot lines on the sheet, by person and oldest first. */
export function useSnapshots() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: snapshotsKey(sheet),
    queryFn: () => getJson<Snapshot[]>(`/api/sheets/${encodeURIComponent(sheet)}/snapshots`),
    enabled: !!sheet,
  });
}
EOF
cat > features/snapshots/PersonSnapshots.tsx <<'EOF'
import type { Person } from '../people/people';
import { useSnapshots } from './snapshots';

// A person's snapshot lines, oldest first: one per SNAPSHOT written for them, as the day being left and their
// due-total on it.
export function PersonSnapshots({ person }: { person: Person }) {
  const snapshots = (useSnapshots().data ?? []).filter((s) => s.personId === person.id);
  return (
    <td>
      {snapshots.map((s, i) => (
        <div key={i} data-testid="person-snapshot-line">
          {s.day} {s.dueTotal}
        </div>
      ))}
    </td>
  );
}
EOF
cat > features/snapshots/snapshots.slot.tsx <<'EOF'
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { PersonSnapshots } from './PersonSnapshots';

export const contributions = [
  PersonColumnHeads.fill({ order: 15.2, Component: () => <th>Snapshots</th> }),
  PersonColumns.fill({ order: 15.2, Component: PersonSnapshots }),
];
EOF
